// Pega a primeira mensagem de texto do payload da Meta.
const cfg = $input.first().json;
const value = cfg.body?.entry?.[0]?.changes?.[0]?.value;
const msg = value?.messages?.[0];
if (!msg || msg.type !== 'text') return [];
return [{ json: {
  de: msg.from,
  nome: value.contacts?.[0]?.profile?.name || '',
  texto: msg.text.body,
  whatsappPhoneId: cfg.whatsappPhoneId,
  telefoneRecepcao: cfg.telefoneRecepcao,
  pedidoIA: {
    model: 'claude-haiku-5-5',
    max_tokens: 400,
    system: cfg.regras,
    messages: [{ role: 'user', content: msg.text.body }]
  }
} }];

